import {useEntitlement} from '@github-ui/copilot-chat/components/quota/EntitlementContext'
import {TraceDisplay} from '@github-ui/copilot-chat/components/tracing/TraceDisplay'
import {useTraceState} from '@github-ui/copilot-chat/components/tracing/TraceProvider'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useSelectedCopilotSpaceId} from '@github-ui/copilot-chat/hooks/use-selected-custom-copilot-id'
import type {CopilotSpaceId} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {CopilotLocalStorage, copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
// eslint-disable-next-line no-restricted-imports
import {useChatState, useChatStateValues} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {getFailedActionsJobPrompt} from '@github-ui/copilot-chat/utils/prompts'
import {useFetchCopilotSpace} from '@github-ui/copilot-spaces/hooks'
import {useSpaceSelection} from '@github-ui/copilot-spaces/hooks/use-space-selection'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import type {AnchorSide} from '@primer/behaviors'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useHandleMessageSubmit} from '../hooks/use-handle-message-submit'
import {useIsSharedThread} from '../hooks/use-is-shared-thread'
import {ChatInputContainer} from './ChatInputContainer'
import styles from './ConversationView.module.css'
import {ErrorFallback} from './ErrorFallback'
import {ImmersiveChat} from './ImmersiveChat'
import {NewConversation} from './NewConversation/NewConversation'
import {NotificationsSection} from './NotificationsSection'
import {spaceConversationVariants, useSpaceConversationStatus} from './Spaces/SpaceConversationBanner'

interface ConversationViewProps {
  isMobile: boolean
  textAreaRef: React.RefObject<HTMLTextAreaElement | null>
  attachmentMenuSide?: AnchorSide
}

function ConversationViewInner({isMobile, textAreaRef, attachmentMenuSide}: ConversationViewProps) {
  const state = useChatState()
  const manager = useChatManager()
  const traceState = useTraceState()
  const {messages, messagesLoading, threadsLoading} = state
  const {chatQuotaExceeded} = useEntitlement()
  const customCopilotId = useSelectedCopilotSpaceId()
  const {data: customCopilot} = useFetchCopilotSpace(customCopilotId)
  const customCopilotExists = Boolean(customCopilot)
  const {variant: spaceViewVariant} = useSpaceConversationStatus(customCopilotId, state.selectedThreadID)
  const spaceSizeExceeded = spaceViewVariant === spaceConversationVariants.customCopilotSizeExceeded
  const showChatInput = (!spaceViewVariant || customCopilotExists) && !spaceSizeExceeded
  const {handleSpaceSelect} = useSpaceSelection()

  const currentTopicRef = useRef(state.currentTopic)
  const isSharedThread = useIsSharedThread()
  const hasEntrypointMessage = useMemo(
    () => !state.selectedThreadID && copilotLocalStorage.getEntrypointMessage(),
    [state.selectedThreadID],
  )
  const shouldShowNewConversation = useMemo(() => {
    if (
      state.selectedThreadID || // If there's a selected thread, we know it's not a new conversation
      state.pendingFirstMessage || // If the user sent a message but the thread hasn't been created yet, show the ImmersiveChat
      hasEntrypointMessage || // If there's an entrypoint message, kick off chat right away
      customCopilotId || // Custom copilots are currently still handled in the ImmersiveChat, should probably be moved up to Layout
      messagesLoading.state === 'error' || // Don't show if there's an error state because we do show the input at the bottom then
      threadsLoading.state === 'error' ||
      state.shouldReplaceHistoryOnNavigation // Don't show if we're about to reroute to a thread.
    ) {
      return false
    }

    return true
  }, [
    state.selectedThreadID,
    state.pendingFirstMessage,
    hasEntrypointMessage,
    customCopilotId,
    messagesLoading.state,
    threadsLoading.state,
    state.shouldReplaceHistoryOnNavigation,
  ])

  const nextMessageIndex = messages.length

  const handleUserSubmit = useHandleMessageSubmit(currentTopicRef, nextMessageIndex)

  useEffect(() => {
    currentTopicRef.current = state.currentTopic
  }, [state.currentTopic])

  useEffect(() => {
    const sendMessage = async (message: NonNullable<ReturnType<CopilotLocalStorage['getEntrypointMessage']>>) => {
      copilotLocalStorage.clearEntrypointMessage(state.selectedThreadID)

      // If the message has a space reference, select that space before submitting the message
      const space = message?.references?.find?.(ref => ref.type === 'copilot-space')
      const copilotSpaceId: CopilotSpaceId | null = space ? {id: space.id, owner: space.owner} : null
      if (copilotSpaceId) handleSpaceSelect(copilotSpaceId)

      // Clear references to avoid duplicates or PR references when redirecting from Actions/PR UI for failed jobs
      const shouldClearReferences =
        isFeatureEnabled('copilot_chat_action_logs_redirect') &&
        message.message === getFailedActionsJobPrompt(undefined, true)
      if (message.model) {
        manager.selectModel(message.model)
      }
      // Set flag to replace history on navigation since this is from an entrypoint
      manager.setShouldReplaceHistoryOnNavigation(true)

      let thread = state.selectedThreadID ? manager.getThreadById(state.selectedThreadID) : null
      if (state.selectedThreadID && !thread && state.threadsLoading.state !== 'loaded') {
        // if the threads haven't loaded yet, wait for them to load so we send to the correct thread
        const threads = await manager.fetchThreads()
        thread = threads?.find(t => t.id === state.selectedThreadID) || null
      }

      // eslint-disable-next-line @eslint-react/web-api/no-leaked-timeout
      setTimeout(() => {
        void handleUserSubmit(
          message.message,
          message.references,
          shouldClearReferences,
          message.model,
          copilotSpaceId, // Pass copilotSpaceId explicitly because React state updates (from handleSpaceSelect above) are asynchronous and may not be reflected in activeCopilotSpaceId yet. This ensures the message is sent with the correct space.
          message.mediaContent,
          thread,
        )
      }, 100)
    }

    const message = copilotLocalStorage.getEntrypointMessage(state.selectedThreadID)
    if (message && !chatQuotaExceeded) {
      void sendMessage(message)
    }
  }, [
    handleUserSubmit,
    chatQuotaExceeded,
    state.currentReferences,
    manager,
    handleSpaceSelect,
    state.selectedThreadID,
    state.threadsLoading.state,
  ])

  const content = (
    <div className={styles.root}>
      {traceState.traceInfo?.visible ? (
        <TraceDisplay sharedThreadChannel={state.sharedThreadChannel} threadId={state.selectedThreadID} />
      ) : (
        <>
          <div className={styles.container}>
            {shouldShowNewConversation ? (
              <NewConversation
                textAreaRef={textAreaRef}
                handleUserSubmit={handleUserSubmit}
                nextMessageIndex={nextMessageIndex}
              />
            ) : (
              <ImmersiveChat inputRef={textAreaRef} isMobile={isMobile} />
            )}
          </div>
          {(!isSharedThread || copilotFeatureFlags.copilotDuplicateThread) && !shouldShowNewConversation && (
            <div className={styles.footer}>
              {!showChatInput && <NotificationsSection />}
              {showChatInput && (
                <ChatInputContainer
                  textAreaRef={textAreaRef}
                  handleUserSubmit={handleUserSubmit}
                  nextMessageIndex={nextMessageIndex}
                  slashCommandsEnabled
                  attachmentMenuSide={attachmentMenuSide}
                />
              )}
            </div>
          )}
        </>
      )}
    </div>
  )

  return content
}

export function ConversationView(props: ConversationViewProps) {
  return (
    <ConversationViewErrorBoundary>
      <ConversationViewInner {...props} />
    </ConversationViewErrorBoundary>
  )
}

export function ConversationViewErrorBoundary(props: {children: React.ReactNode}) {
  const {selectedThreadID} = useChatStateValues('selectedThreadID')
  const [key, setKey] = useState(0)
  const hasErrored = useRef(false)
  const onError = useCallback(() => {
    hasErrored.current = true
  }, [])

  // If we had an error, and then change threads, change the key to reset the error state.
  useEffect(() => {
    if (!copilotFeatureFlags.stableConversationView) return

    if (hasErrored.current) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setKey(prev => prev + 1)
      hasErrored.current = false
    }
  }, [selectedThreadID])

  return (
    <ErrorBoundary key={key} fallback={<ErrorFallback regionName="This conversation" />} onError={onError}>
      {props.children}
    </ErrorBoundary>
  )
}

try{ ConversationViewInner.displayName ||= 'ConversationViewInner' } catch {}
try{ ConversationView.displayName ||= 'ConversationView' } catch {}
try{ ConversationViewErrorBoundary.displayName ||= 'ConversationViewErrorBoundary' } catch {}