import {useCreateTask} from '@github-ui/agent-sessions/hooks/useCreateTask'
import type {SelectedAgent} from '@github-ui/agent-sessions/types/session'
import type {CreateTaskMutationParams} from '@github-ui/agent-sessions/types/task'
import {TraceProvider} from '@github-ui/copilot-chat/components/tracing/TraceProvider'
import {ImmersivePluginsProvider} from '@github-ui/copilot-chat/plugin/registry'
import type {AgentDropdownRepository} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {copilotLocalStorage} from '@github-ui/copilot-chat/utils/copilot-local-storage'
import {CopilotChatProvider} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import {NavigableRefProvider} from '@github-ui/navigable-ref'
// eslint-disable-next-line no-restricted-imports
import {ScreenSizeProvider} from '@github-ui/screen-size'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useImmersivePlugins} from '../hooks/use-immersive-plugins'
import {useRouteThreadId} from '../hooks/use-route-thread-id'
import type {CopilotImmersivePayload} from '../routes/payloads'
import {ContentPreviewProvider} from './ContentPreview/ContentPreviewContext'

export function CopilotImmersiveProviders({
  payload,
  children,
}: React.PropsWithChildren<{payload: CopilotImmersivePayload}>) {
  const threadId = useRouteThreadId()
  const {refs, topic} = useMemo(() => {
    const requestedTopic = payload.requestedTopic
    if (payload.reference) {
      return {refs: [payload.reference], topic: requestedTopic}
    } else {
      return {refs: [], topic: requestedTopic}
    }
  }, [payload.requestedTopic, payload.reference])

  // TODO: handle displaying failed tasks
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [_failedTasks, setFailedTasks] = useState<CreateTaskMutationParams[]>([])

  const {createTask} = useCreateTask({
    onError: (_, variables) => {
      setFailedTasks(prev => [{...variables}, ...prev])
    },
  })

  const handleUserSubmit = useCallback(
    (
      content: string,
      selectedRepo: AgentDropdownRepository | null,
      selectedBranch: string,
      selectedAgent: SelectedAgent,
    ) => {
      const trimmedContent = content.trim()
      if (trimmedContent === '' || !selectedBranch || selectedBranch.trim() === '') return
      if (selectedRepo) {
        // This mutation will automatically invalidate and refetch the tasks after completion
        createTask({
          nwo: selectedRepo.nameWithOwner,
          problemStatement: trimmedContent,
          baseRef: selectedBranch,
          eventType: 'immersive_page',
          eventContent: trimmedContent,
          selectedAgent,
        })
      }
    },
    [createTask],
  )

  const handleUserSubmitRef = useRef(handleUserSubmit)

  useEffect(() => {
    if (payload.reference?.type === 'repository') {
      copilotLocalStorage.setLastUsedRepository(payload.reference)
    }
  }, [payload.reference])

  useEffect(() => {
    handleUserSubmitRef.current = handleUserSubmit
  }, [handleUserSubmit])

  const plugins = useImmersivePlugins({payload, handleUserSubmitRef})

  return (
    <NavigableRefProvider>
      <ScreenSizeProvider>
        <ImmersivePluginsProvider plugins={plugins}>
          <TraceProvider apiURL={payload.apiURL} ssoOrgs={payload.ssoOrganizations}>
            <CopilotChatProvider
              workerPath={payload.searchWorkerFilePath}
              threadId={threadId}
              refs={refs}
              mode="immersive"
              topic={topic}
              ssoOrganizations={payload.ssoOrganizations}
              copilotChatPayload={payload}
            >
              <ContentPreviewProvider>{children}</ContentPreviewProvider>
            </CopilotChatProvider>
          </TraceProvider>
        </ImmersivePluginsProvider>
      </ScreenSizeProvider>
    </NavigableRefProvider>
  )
}

try{ CopilotImmersiveProviders.displayName ||= 'CopilotImmersiveProviders' } catch {}