import type {
  CopilotChatMessage,
  DraftIssueReference,
  ExistingIssueReference,
} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import {useMemo} from 'react'

import {ContentPreviewBlockContext} from '../markdown-extensions/ContentPreviewBlockContext'
import {DraftIssueTreeBlock} from '../markdown-extensions/issue-blocks/draft-issue-tree/DraftIssueTreeBlock'

interface DraftIssueReferenceRendererProps {
  message: CopilotChatMessage
  messageIndex: number
  autoOpenPreviewPane: boolean
}

/**
 * Check if the message content already contains a draft issue YAML block.
 * These YAML blocks are rendered by the markdown extension and we don't want to duplicate the rendering.
 * Detects patterns like:
 * - ```yaml type=draft-issue
 * - ```yaml type=draft-issue-tree
 * - ```yaml type=draft-update-issue
 */
function hasDraftIssueYamlBlock(content: string | undefined): boolean {
  if (!content) return false

  // Match ```yaml type=draft-issue, type="draft-issue", type=draft-issue-tree, type="draft-issue-tree", etc.
  const yamlBlockPattern = /```yaml\s+type=["']?(draft-issue|draft-issue-tree|draft-update-issue)["']?/i
  return yamlBlockPattern.test(content)
}

/**
 * Renders draft and existing issue references using the DraftIssueTreeBlock component.
 * This component filters message references to include draft-issue, draft-update-issue,
 * and existing-issue types, then renders them in a tree view structure.
 *
 * Will not render if the message already contains YAML blocks for draft issues,
 * as those are handled by markdown extensions to avoid duplicate rendering.
 */
export function DraftIssueReferenceRenderer({
  message,
  messageIndex,
  autoOpenPreviewPane,
}: DraftIssueReferenceRendererProps) {
  // Context value for DraftIssueBlock components
  const draftIssueBlockContext = useMemo(
    () => ({
      messageId: message.id,
      messageIndex,
      messageTimestamp: message.createdAt,
      autoOpenPreviewPane,
      markdown: message.content || '',
      hasAutoOpenedPreviewPaneRef: {current: false},
      setHasAutoOpenedPreviewPane: () => {},
    }),
    [message.id, messageIndex, message.createdAt, autoOpenPreviewPane, message.content],
  )

  const references = useMemo(() => {
    return (message.references || []).filter(
      (ref): ref is DraftIssueReference | ExistingIssueReference =>
        ref.type === 'draft-issue' || ref.type === 'draft-update-issue' || ref.type === 'existing-issue',
    )
  }, [message.references])

  // Don't render if the message already has YAML blocks - they'll be rendered by markdown extensions
  if (hasDraftIssueYamlBlock(message.content)) {
    return null
  }

  if (references.length === 0) return null

  return (
    <div className="mt-3">
      <ContentPreviewBlockContext.Provider key="draft-issue-tree" value={draftIssueBlockContext}>
        <DraftIssueTreeBlock references={references} />
      </ContentPreviewBlockContext.Provider>
    </div>
  )
}

try{ DraftIssueReferenceRenderer.displayName ||= 'DraftIssueReferenceRenderer' } catch {}