import {ChatInput, type ChatInputProps, type ChatInputRef} from '@github-ui/copilot-chat/components/ChatInput'
import {useEntitlement} from '@github-ui/copilot-chat/components/quota/EntitlementContext'
import {useNavigateToNewThread} from '@github-ui/copilot-chat/hooks/use-navigate-to-new-thread'
import {useSelectedCopilotSpaceId} from '@github-ui/copilot-chat/hooks/use-selected-custom-copilot-id'
import {useSSOOrgNames} from '@github-ui/copilot-chat/hooks/use-sso-org-names'
import {type CopilotChatReference, ModeSupportName} from '@github-ui/copilot-chat/utils/copilot-chat-types'
// eslint-disable-next-line no-restricted-imports
import {useChatState} from '@github-ui/copilot-chat/utils/CopilotChatContext'
import type {AnchorSide} from '@primer/behaviors'
import {CommentIcon} from '@primer/octicons-react'
import {useMemo} from 'react'

import {useFigmaAuthUrl} from '../hooks/use-figma-auth-url'
import {useOnReferenceSelect} from '../hooks/use-on-reference-select'
import {getItemVersionForReference} from './ContentPreview/content-preview-types'
import {useContentPreview} from './ContentPreview/ContentPreviewContext'
import styles from './Layout.module.css'
import {NotificationsSection} from './NotificationsSection'

interface ChatInputContainerProps {
  activeModeName?: string
  onClickMode?: (modeName: string) => void
  textAreaRef: React.RefObject<HTMLTextAreaElement | null>
  chatInputRef?: React.RefObject<ChatInputRef | null>
  handleUserSubmit: (
    content: string,
    additionalReferences?: CopilotChatReference[],
    clearReferencesFirst?: boolean,
  ) => Promise<void>
  nextMessageIndex: number
  containerRef?: React.RefObject<HTMLFormElement | null>
  isNewConversation?: boolean
  onChatCommandChange?: ChatInputProps['onChatCommandChange']
  slashCommandsEnabled?: ChatInputProps['slashCommandsEnabled']
  showDisabledInputOnQuotaExceeded?: boolean
  attachmentMenuSide?: AnchorSide
}

export function ChatInputContainer({
  activeModeName,
  onClickMode,
  textAreaRef,
  handleUserSubmit,
  nextMessageIndex,
  chatInputRef,
  isNewConversation,
  onChatCommandChange,
  containerRef,
  slashCommandsEnabled,
  showDisabledInputOnQuotaExceeded = false,
  attachmentMenuSide,
}: ChatInputContainerProps) {
  const state = useChatState()
  const {chatQuotaExceeded, isLicensedLimited} = useEntitlement()

  // Check if the user has missing SSO organizations
  const {needsSsoAuthentication} = useSSOOrgNames()
  const selectedCopilotSpaceId = useSelectedCopilotSpaceId()
  const hideChatInput = needsSsoAuthentication && selectedCopilotSpaceId

  const navigateToNewThread = useNavigateToNewThread()
  const figmaAuthUrl = useFigmaAuthUrl()

  const onInputReferenceSelect = useOnReferenceSelect({messageIndex: nextMessageIndex})

  const {versionedItems, items} = useContentPreview()

  const existingFileNames = useMemo(() => {
    const result = new Set<string>()
    for (const [, item] of items) if (item.type === 'file') result.add(item.name)
    return result
  }, [items])

  const quotaExceeded = isLicensedLimited && chatQuotaExceeded
  const canUseChat = !quotaExceeded && !hideChatInput
  const shouldShowInput = canUseChat || (quotaExceeded && showDisabledInputOnQuotaExceeded)

  return (
    <div className={styles.chatInputContainer}>
      <NotificationsSection />
      {shouldShowInput && (
        <ChatInput
          activeModeName={activeModeName}
          onClickMode={onClickMode}
          modes={[
            {
              name: ModeSupportName.Ask,
              supportsMCP: !selectedCopilotSpaceId,
              supportsAttachments: true,
              supportsModelSwitching: true,
              supportsSpaces: true,
              supportsAutocompletion: true,
              icon: CommentIcon,
              placeholder:
                state.usePlanningIntent && !state.selectedThreadID ? 'What would you like to create?' : 'Ask anything',
            },
          ]}
          onNewThreadSelected={navigateToNewThread}
          textAreaRef={textAreaRef}
          chatInputRef={chatInputRef}
          containerRef={containerRef}
          onSubmit={handleUserSubmit}
          isStreaming={!!state.streamingMessage}
          size="large"
          showPlanningToggle={!state.selectedThreadID}
          onSelectReference={onInputReferenceSelect}
          getReferenceVersion={reference => getItemVersionForReference(reference, nextMessageIndex, versionedItems)}
          existingFileNames={existingFileNames}
          figmaAuthUrl={figmaAuthUrl}
          isNewConversation={isNewConversation}
          onChatCommandChange={onChatCommandChange}
          disableSavedUserMessage
          slashCommandsEnabled={slashCommandsEnabled}
          disabled={quotaExceeded}
          attachmentMenuSide={attachmentMenuSide}
        />
      )}
    </div>
  )
}

try{ ChatInputContainer.displayName ||= 'ChatInputContainer' } catch {}